// Generates src/lib/soul.generated.ts from soul.md so the server bundle carries
// the exact same text the local companion reads. soul.md is the only source.
import { readFile, writeFile } from "node:fs/promises";
const soul = await readFile(new URL("../soul.md", import.meta.url), "utf8");
await writeFile(
  new URL("../src/lib/soul.generated.ts", import.meta.url),
  "// Generated by scripts/build-soul.mjs from soul.md. Edit soul.md, then run npm run build:soul.\nexport const soul = " + JSON.stringify(soul) + ";\n",
);
console.log("soul.generated.ts written from soul.md");
